function bounded(promise,ms,label){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(label+" timed out")),ms)})]).finally(()=>clearTimeout(timer));}
function step(text){steps.push(text);console.log(`[native-browser] ${text}`);}
function launch(command,args,env,label){const child=spawn(command,args,{cwd:label==="vite"?join(root,"frontend"):root,env:{...process.env,...env},windowsHide:label!=="tauri",stdio:["ignore","pipe","pipe"]});for(const s of [child.stdout,child.stderr])s.on("data",x=>{const line=`[${label}] ${x}`;logs.push(line);void appendFile(join(evidence,"services-live.log"),line);});void appendFile(join(evidence,"children.jsonl"),JSON.stringify({label,pid:child.pid})+"\n");child.on("exit",(code,signal)=>{const line=`[${label}] exit code=${code} signal=${signal}\n`;logs.push(line);void appendFile(join(evidence,"services-live.log"),line);});children.push(child);return child;}
async function until(read,predicate,label,timeout=40000){const end=Date.now()+timeout;let value;while(Date.now()<end){try{value=await bounded(Promise.resolve().then(read),10000,label+" read");if(predicate(value))return value;}catch(e){value=String(e);}await new Promise(r=>setTimeout(r,150));}throw new Error(`${label}: ${JSON.stringify(value)}`);}
async function listen(server){servers.push(server);await new Promise(r=>server.listen(0,"127.0.0.1",r));return server.address().port;}
async function freePort(){const server=createServer();await new Promise(r=>server.listen(0,"127.0.0.1",r));const port=server.address().port;await new Promise(r=>server.close(r));return port;}
async function invoke(command,args={}){return bounded(main.evaluate(({command,args})=>window.__TAURI_INTERNALS__.invoke(command,args),{command,args}),35000,command);}
async function tabs(){return invoke("native_browser_tabs");}
async function current(id){return (await tabs()).find(t=>t.tab_id===id);}
function target(tab){return {session_id:tab.session_id,tab_id:tab.tab_id,navigation_id:tab.navigation_id};}
async function execute(action,payload={},tab,operation_id=randomUUID()){return invoke("native_browser_execute",{request:{operation_id,action,target:tab?target(tab):null,payload,owner:null}});}
async function observe(tab){const reply=await execute("observe",{},await current(tab.tab_id));assert.equal(reply.state,"verified");assert.ok(!reply.data.observation.text.includes("PRIVILEGED_IPC_EXPOSED"),"external page obtained a privileged IPC reply");return reply.data.observation;}
async function api(method,path,body,expected=200){const response=await fetch(base+path,{method,signal:AbortSignal.timeout(20000),headers:{"Content-Type":"application/json","X-Yilian-Control-Session":token},body:body===undefined?undefined:JSON.stringify(body)});const text=await response.text();assert.equal(response.status,expected,`${method} ${path}: ${text}`);return text?JSON.parse(text):null;}
async function shot(name){await main.screenshot({path:join(evidence,name),animations:"disabled",timeout:8000});}
async function capture(tab,name){const reply=await execute("capture",{},await current(tab.tab_id));assert.equal(reply.state,"verified");const encoded=reply.data.data_base64;assert.equal(typeof encoded,"string");const bytes=Buffer.from(encoded,"base64");assert.ok(bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])));await writeFile(join(evidence,name),bytes);return {width:bytes.readUInt32BE(16),height:bytes.readUInt32BE(20)};}
async function nativePermissionAndDownloadCoverage(project){
 const permissionOpen=await execute("open",{url:fixtureUrl+"/permission-probe",workspace_id:project.id,ephemeral:true,allowed_origins:[fixtureUrl]});assert.equal(permissionOpen.state,"verified");const permissionTab=permissionOpen.data.tab;
 let observation=await observe(permissionTab);const geoId=randomUUID();const geolocation=await execute("click",{observation_id:observation.observation_id,element_id:observation.elements.find(element=>element.name==="Request native geolocation").element_id},await current(permissionTab.tab_id),geoId);assert.equal(geolocation.state,"result_unknown");
 const permission=await until(()=>invoke("native_browser_ui_state"),state=>state.requests.some(item=>item.tab_id===permissionTab.tab_id&&item.kind==="permission"),"native permission waits for trusted decision");
 const request=permission.requests.find(item=>item.tab_id===permissionTab.tab_id&&item.kind==="permission");await invoke("native_browser_resolve_request",{id:request.id,decision:"deny"});
 observation=await until(()=>observe(permissionTab),value=>value.text.includes("GEO_DENIED:"),"explicit native geolocation denial");assert.ok(observation.text.includes("GEO_DENIED:1"));assert.ok(!observation.text.includes("UNEXPECTED_LOCATION_GRANTED"));await capture(permissionTab,"native-geolocation-denied.png");
 await invoke("native_browser_acknowledge_unknown",{operationId:geoId});await execute("close",{},await current(permissionTab.tab_id));permissionProofs.push({kind:"geolocation",trusted_pending:true,decision:"deny",native_page_callback:"PERMISSION_DENIED",coordinates_read:false});step("A real permission request waits for a trusted choice; explicit denial reaches its native page without reading coordinates");
 const downloadOpen=await execute("open",{url:fixtureUrl+"/download-probe",workspace_id:project.id,ephemeral:true,allowed_origins:[fixtureUrl]});assert.equal(downloadOpen.state,"verified");const downloadTab=downloadOpen.data.tab;observation=await observe(downloadTab);const downloadId=randomUUID();
 const clicked=await execute("click",{observation_id:observation.observation_id,element_id:observation.elements.find(element=>element.name==="Download controlled file").element_id},await current(downloadTab.tab_id),downloadId);assert.equal(clicked.state,"result_unknown");
 const download=await until(()=>invoke("native_browser_ui_state"),state=>state.requests.some(item=>item.tab_id===downloadTab.tab_id&&item.kind==="download"),"native download requires destination choice");
 const downloadRequest=download.requests.find(item=>item.tab_id===downloadTab.tab_id&&item.kind==="download");assert.ok(fixtureRequests.includes("/controlled-download"));await shot("native-download-pending.png");await invoke("native_browser_resolve_request",{id:downloadRequest.id,decision:"deny"});
 const readable=await until(()=>observe(downloadTab),value=>value.text.includes("Native download denial"),"original document readable after download cancellation");assert.ok(readable);
 const ownFiles=await readdir(isolated,{recursive:true});assert.ok(!ownFiles.some(path=>path.split(/[\\/]/).at(-1)===deniedDownloadName));permissionProofs.push({kind:"download",trusted_pending:true,decision:"deny",controlled_endpoint_requested:true,owned_named_file_count:0,user_directories_inspected:false});
 await invoke("native_browser_acknowledge_unknown",{operationId:downloadId});await execute("close",{},await current(downloadTab.tab_id));step("A real attachment waits for a trusted destination, can be cancelled without saving, and leaves its native page readable");
}
async function approvalDecisionCoverage(tab,project,mode){
 const original=await observe(tab),draft=original.elements.find(e=>e.name==="Draft");assert.ok(draft);const marker=`NATIVE_PENDING_${mode.toUpperCase()}`;pendingSeeds.set(marker,{target:target(await current(tab.tab_id)),observation_id:original.observation_id,element_id:draft.element_id,value:`must-not-dispatch-${mode}`});const conversation=await api("POST","/api/conversations",{title:`Native ${mode} approval fixture`});await api("PUT",`/api/conversations/${conversation.id}/workspace`,{workspace_id:project.id});const response=await fetch(base+"/api/chat",{method:"POST",signal:AbortSignal.timeout(45000),headers:{"Content-Type":"application/json","X-Yilian-Control-Session":token},body:JSON.stringify({conversation_id:conversation.id,message:marker})});assert.equal(response.status,200);await response.text();const pending=await until(async()=>{const result=await api("GET","/api/approvals/pending");return result.approvals.find(item=>item.conversation_id===conversation.id)},Boolean,"independent native approval pending");assert.equal(pending.tool_name,"visible_browser_fill");
 if(mode==="reject"){const denied=await fetch(`${base}/api/approvals/${pending.approval_id}/reject`,{method:"POST",signal:AbortSignal.timeout(45000),headers:{"Content-Type":"application/json","X-Yilian-Control-Session":token},body:JSON.stringify({conversation_id:conversation.id})});assert.equal(denied.status,200);await denied.text();}else await api("POST","/api/chat/stop",{conversation_id:conversation.id});
 const expected=mode==="reject"?"rejected":"cancelled";await until(()=>api("GET",`/api/approvals/${pending.approval_id}`),result=>result.approval?.status===expected,"persisted terminal approval decision");const late=await fetch(`${base}/api/approvals/${pending.approval_id}/approve`,{method:"POST",signal:AbortSignal.timeout(15000),headers:{"Content-Type":"application/json","X-Yilian-Control-Session":token},body:JSON.stringify({conversation_id:conversation.id})});assert.equal(late.status,409,await late.text());const after=await observe(tab);assert.equal(after.elements.find(e=>e.name==="Draft").value,draft.value,"rejected/cancelled and late-approved action must never fill the real page");assert.equal((await api("GET",`/api/approvals/${pending.approval_id}`)).approval.status,expected);approvalProofs.push({mode,approval_id:pending.approval_id,status:expected,late_status:late.status,form_unchanged:true});step(`Real Gateway ${mode} prevents a pending native Fill; late approval conflicts and visible form stays unchanged`);
}
async function measureGeometry(label,width){const result=await main.evaluate(()=>({viewport:innerWidth,outerWidth:outerWidth,dpr:devicePixelRatio,documentWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,canvas:(()=>{const r=document.querySelector('[data-testid="native-browser-viewport"]')?.getBoundingClientRect();return r?{x:r.x,y:r.y,width:r.width,height:r.height}:null})(),dialogs:[...document.querySelectorAll('[role="dialog"]')].map(d=>({width:d.clientWidth,scrollWidth:d.scrollWidth}))}));assert.ok(result.scrollWidth<=result.documentWidth+2);for(const d of result.dialogs)assert.ok(d.scrollWidth<=d.width+2);geometry.push({label,requestedCssWidth:width,...result,boundary:"CSS viewport stress; product physical main minimum remains 800px, not a claim of mobile or 390px physical-window support"});return result;}
async function layoutStress(tab){let previous=Infinity;for(const width of [1366,960,390]){await main.setViewportSize({width,height:768});const measured=await measureGeometry("native-child",width);assert.ok(measured.canvas?.width>0);await execute("present",{mode:"embedded",...measured.canvas},await current(tab.tab_id));const image=await capture(tab,`native-child-${width}.png`);assert.ok(image.width>0&&image.height>0);assert.ok(image.width<previous,"actual native child PNG must become narrower with the requested CSS layout");previous=image.width;geometry[geometry.length-1].nativePng=image;await shot(`trusted-toolbar-${width}.png`);}await main.setViewportSize({width:1366,height:768});const measured=await measureGeometry("restore-layout",1366);await execute("present",{mode:"embedded",...measured.canvas},await current(tab.tab_id));step("Trusted UI CSS stress at 1366/960/390 has no horizontal overflow and actual native child PNG widths follow controller resizing; physical minimum remains unchanged");}
